import 'dart:io';

import 'src/concord_schema.dart';

const concordTiersOutput = 'lib/features/editor/generated/concord_tiers.dart';

String renderConcordTiers(ConcordSchema schema) {
  final out = StringBuffer()
    ..writeln(
      '// Generated by `dart run tool/generate_concord_tiers.dart` from',
    )
    ..writeln('// `$concordSchemaPath`. Do not edit.')
    ..writeln()
    ..writeln('enum ConcordTier { ${concordTiers.join(', ')} }')
    ..writeln()
    ..writeln('const concordKeyTiers = <String, Map<String, ConcordTier>>{');
  for (final MapEntry(key: section, value: tiers) in schema.sections.entries) {
    out.writeln("  '$section': {");
    for (final MapEntry(:key, :value) in tiers.entries) {
      out.writeln("    '$key': ConcordTier.$value,");
    }
    out.writeln('  },');
  }
  out.writeln('};');
  for (final MapEntry(key: section, value: keys) in schema.values.entries) {
    for (final MapEntry(:key, :value) in keys.entries) {
      final names = value.map((name) => "'$name'").join(', ');
      out
        ..writeln()
        ..writeln('const ${concordValuesName(section, key)} = [$names];');
    }
  }
  return out.toString();
}

String concordValuesName(String section, String key) {
  final words = [
    'concord',
    if (section != 'keys') section,
    ...key.split(RegExp('[-.]')),
  ];
  return words.first +
      words.skip(1).map((w) => w[0].toUpperCase() + w.substring(1)).join();
}

void main(List<String> args) {
  final check = args.contains('--check');
  final rendered = renderConcordTiers(ConcordSchema.load());
  final file = File(concordTiersOutput);
  if (!check) {
    file
      ..createSync(recursive: true)
      ..writeAsStringSync(rendered);
    return;
  }
  if (!file.existsSync() || file.readAsStringSync() != rendered) {
    stderr.writeln(
      '$concordTiersOutput is out of date with $concordSchemaPath; '
      'run `dart run tool/generate_concord_tiers.dart`.',
    );
    exitCode = 1;
  }
}
